use xiom.io;

use xiom.string;
use xiom.iter;
fn main() -> Int {
  let animals: Vec[Str] = Vec[Str].new();
  animals.push("cat");
  animals.push("dog");
  animals.push("owl");

  for __i in range(0, animals.len()) {
    let animal = animals[__i];
    io.println(animal.to_str());
  }

  io.println("Total: " + to_string(animals.len()));
  return 0;
}
